def embed_documents_from_tokens(token_list, label_list, tokenizer, model, device, max_length):
    """Wrapper to match embed_documents interface."""
    docs = [{'id': i, 'tokens': t, 'token_labels': l} for i, (t, l) in enumerate(zip(token_list, label_list))]
    return embed_documents(docs, tokenizer, model, device, max_length)
